// middleware.js — proteção de senha única pro site inteiro (PSCPP Tracker)
//
// Como funciona:
// 1. Toda requisição passa por aqui primeiro (antes de qualquer HTML/imagem/API ser entregue)
// 2. Se já tiver um cookie válido (token assinado, não a senha em texto puro), deixa passar
// 3. Se não tiver, mostra a tela de senha (HTML embutido aqui mesmo, com a logo em base64
//    pra não depender de nenhuma requisição extra que também cairia na trava)
// 4. Ao enviar a senha certa, grava um cookie assinado (HMAC) válido por 30 dias
//
// Variáveis de ambiente necessárias (cadastrar no painel da Vercel, Settings → Environment Variables):
// - SITE_PASSWORD: a senha de acesso ao site (texto simples, só você sabe)
// - SITE_AUTH_SECRET: uma string aleatória longa, usada só pra assinar o cookie
//   (gera uma com, por exemplo: openssl rand -hex 32 no terminal, ou qualquer gerador de senha longa)

export const config = {
  matcher: '/:path*',
};

const COOKIE_NAME = 'pscpp_auth';
const ICON_BASE64 = '';
const LOGO_BASE64 = '';

async function gerarToken(segredo) {
  const enc = new TextEncoder();
  const key = await crypto.subtle.importKey(
    'raw', enc.encode(segredo), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']
  );
  const assinatura = await crypto.subtle.sign('HMAC', key, enc.encode('autorizado'));
  return Array.from(new Uint8Array(assinatura)).map(b => b.toString(16).padStart(2, '0')).join('');
}

function paginaSenha(mostrarErro) {
  return `<!DOCTYPE html>
<html lang="pt-BR">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>PSCPP Tracker</title>
<link rel="apple-touch-icon" href="data:image/png;base64,${ICON_BASE64}">
<style>
*{box-sizing:border-box;margin:0;padding:0}
body{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;background:#F9F9F7;display:flex;align-items:center;justify-content:center;min-height:100vh;padding:24px}
.login-inner{width:100%;max-width:432px}
input{padding:6px 10px;border-radius:6px;border:0.5px solid #ddd;margin-bottom:10px;width:100%;background:#fff;color:#111;font-size:16px}
.campo-senha-wrapper{position:relative}
.btn-revelar-senha{position:absolute;right:6px;top:0;bottom:10px;display:flex;align-items:center;background:none;border:none;padding:4px;color:#888;cursor:pointer}
.btn-primario{background:#202A45;color:#fff;border-radius:8px;padding:10px;font-size:16px;font-weight:500;width:100%;border:none;cursor:pointer;font-family:inherit}
.erro{color:#B00020;font-size:14px;margin-bottom:8px;display:${mostrarErro ? 'block' : 'none'}}
</style>
</head>
<body>
<div class="login-inner">
  <div style="text-align:center;margin-bottom:16px">
    <img src="data:image/png;base64,${LOGO_BASE64}" alt="PSCPP Tracker" style="height:32px;width:auto">
  </div>
  <form method="POST" action="/__auth">
    <div class="campo-senha-wrapper">
      <input type="password" name="senha" id="senha-acesso" placeholder="Senha" autocomplete="current-password" required autofocus>
      <button type="button" class="btn-revelar-senha" onclick="const c=document.getElementById('senha-acesso');c.type=c.type==='password'?'text':'password'" aria-label="Mostrar senha">
        <svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M17.94 17.94A10.94 10.94 0 0 1 12 20c-7 0-11-8-11-8a18.5 18.5 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19M14.12 14.12a3 3 0 1 1-4.24-4.24"/><line x1="1" y1="1" x2="23" y2="23"/></svg>
      </button>
    </div>
    <div class="erro">Senha incorreta. Tenta de novo.</div>
    <button class="btn-primario" type="submit">Entrar</button>
  </form>
</div>
</body>
</html>`;
}

export default async function middleware(request) {
  const url = new URL(request.url);
  const tokenEsperado = await gerarToken(process.env.SITE_AUTH_SECRET);

  // já tem cookie válido? deixa passar sem mostrar nada
  const cookieHeader = request.headers.get('cookie') || '';
  const temCookieValido = cookieHeader
    .split(';')
    .map(c => c.trim())
    .includes(`${COOKIE_NAME}=${tokenEsperado}`);

  if (temCookieValido) {
    return; // não retornar nada = deixa a requisição seguir normalmente
  }

  // envio do formulário de senha
  if (request.method === 'POST' && url.pathname === '/__auth') {
    const form = await request.formData();
    const senhaDigitada = form.get('senha');

    if (senhaDigitada === process.env.SITE_PASSWORD) {
      const headers = new Headers();
      headers.append(
        'Set-Cookie',
        `${COOKIE_NAME}=${tokenEsperado}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=2592000`
      );
      headers.append('Location', '/');
      return new Response(null, { status: 302, headers });
    }

    return new Response(paginaSenha(true), {
      status: 401,
      headers: { 'content-type': 'text/html; charset=utf-8' },
    });
  }

  // qualquer outra requisição sem cookie válido: mostra a tela de senha
  return new Response(paginaSenha(false), {
    status: 401,
    headers: { 'content-type': 'text/html; charset=utf-8' },
  });
}
